import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        int c = scanner.nextInt();

        for (int i = 0; i <= c / a; i++) {
            int y = c - a * i;
            if (y % b == 0) {
                System.out.print("Yes");
                return;
            }
        }
        System.out.print("No");
    }
}

